// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address to0, address to1, uint256 v) public {
        Recorder rec = new Recorder();
        address[] memory tos = new address[](2);
        tos[0] = to0;
        tos[1] = to1;

        bool ok; try c.transfer(from, address(rec), tos, v) { ok = true; } catch { ok = false; }

        assertTrue(ok && rec.matchCount() == tos.length);
    }
}

contract Recorder {
    uint256 public matchCount;

    function transferFrom(address, address, uint256) external returns (bool) {
        matchCount += 1;
        return true;
    }
}
